"use client";

import * as React from "react";

import { cn } from "@/lib/utils";

/**
 * Airy docs Label: medium Inter at 0.875rem in full ink, so a field is named
 * clearly above a quiet grey box. A disabled control greys its label too.
 *
 * Base UI has no label primitive, so this is a native label. Base UI marks
 * a disabled control with data-disabled, so the label watches that as well
 * as the native disabled state.
 */
const Label = React.forwardRef<
  HTMLLabelElement,
  React.ComponentPropsWithoutRef<"label">
>(({ className, ...props }, ref) => (
  <label
    ref={ref}
    data-slot="label"
    className={cn(
      "flex select-none items-center gap-2 text-sm font-medium leading-none text-foreground",
      "peer-disabled:cursor-not-allowed peer-disabled:text-(--foreground-disabled)",
      "peer-data-[disabled]:cursor-not-allowed peer-data-[disabled]:text-(--foreground-disabled)",
      className,
    )}
    {...props}
  />
));
Label.displayName = "Label";

export { Label };
